var benchmarkBytes []byte

func BenchmarkEncode(b *testing.B) {
    input := []byte("catalog-item")
    b.ReportAllocs()
    b.ResetTimer()
    for i := 0; i < b.N; i++ {
        out := append([]byte(nil), input...)
        benchmarkBytes = out
        if len(out) != len(input) { b.Fatal("short copy") }
    }
}

func FuzzIntegerRoundTrip(f *testing.F) {
    f.Add("12")
    f.Add("-1")
    f.Fuzz(func(t *testing.T, raw string) {
        if len(raw) > 128 { t.Skip() }
        n, err := strconv.Atoi(raw)
        if err != nil { return }
        again, err := strconv.Atoi(strconv.Itoa(n))
        if err != nil || again != n { t.Fatal("integer round trip") }
    })
}

