func TestDelayedResult(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		done := make(chan struct{})
		go func() { time.Sleep(5 * time.Second); close(done) }()
		synctest.Wait()
		select {
		case <-done:
			t.Fatal("completed before the deadline")
		default:
		}
		time.Sleep(5 * time.Second)
		synctest.Wait()
		select {
		case <-done:
		default:
			t.Fatal("result not published")
		}
	})
}

