	done           bool
}

func (c *Rename) Do() {
	if c.done {
		return
	}
	c.previous = *c.target
	*c.target = c.next
	c.done = true
}
func (c *Rename) Undo() {
	if !c.done {
		return
	}
	*c.target = c.previous
	c.done = false
}

