package main

import (
	"errors"
	"fmt"
	"math/big"
	"strings"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/params"
)

// FeePolicy is owned by the signing service, not by the fee oracle.
type FeePolicy struct {
	MaxFeePerGas *big.Int // highest maxFeePerGas the service will sign
	MaxTotalFee  *big.Int // highest gasLimit * maxFeePerGas, in wei
}

var errAbovePolicy = errors.New("refusing to sign")

func gwei(n int64) *big.Int {
	return new(big.Int).Mul(big.NewInt(n), big.NewInt(params.GWei))
}

// formatGwei prints a non-negative wei amount as gwei without floating point.
func formatGwei(wei *big.Int) string {
	q, r := new(big.Int).QuoRem(wei, big.NewInt(params.GWei), new(big.Int))
	if r.Sign() == 0 {
		return q.String() + " gwei"
	}
	frac := strings.TrimRight(fmt.Sprintf("%09d", r.Uint64()), "0")
	return q.String() + "." + frac + " gwei"
}

// feeCapFor leaves room for the base fee to double before inclusion.
func feeCapFor(baseFee, tip *big.Int) *big.Int {
	c := new(big.Int).Mul(baseFee, big.NewInt(2))
	return c.Add(c, tip)
}

// effectivePrice is min(feeCap, baseFee+tipCap). Below baseFee it is not includable.
func effectivePrice(baseFee, tipCap, feeCap *big.Int) (*big.Int, error) {
	if feeCap.Cmp(baseFee) < 0 {
		return nil, errors.New("max fee below base fee")
	}
	p := new(big.Int).Add(baseFee, tipCap)
	if p.Cmp(feeCap) > 0 {
		p.Set(feeCap)
	}
	return p, nil
}

func checkPolicy(p FeePolicy, gas uint64, tipCap, feeCap *big.Int) error {
	if tipCap.Sign() < 0 || feeCap.Sign() <= 0 || tipCap.Cmp(feeCap) > 0 {
		return errors.New("need 0 <= max priority fee <= max fee")
	}
	if feeCap.Cmp(p.MaxFeePerGas) > 0 {
		return fmt.Errorf("%w: max fee %s > limit %s", errAbovePolicy, formatGwei(feeCap), formatGwei(p.MaxFeePerGas))
	}
	worst := new(big.Int).Mul(new(big.Int).SetUint64(gas), feeCap)
	if worst.Cmp(p.MaxTotalFee) > 0 {
		return fmt.Errorf("%w: worst-case fee %s wei > limit %s wei", errAbovePolicy, worst, p.MaxTotalFee)
	}
	return nil
}

func main() {
	policy := FeePolicy{MaxFeePerGas: gwei(100), MaxTotalFee: big.NewInt(3_000_000_000_000_000)}
	const gasLimit = 21_000
	baseFee, tip := gwei(30), gwei(2) // observed from the latest header and a tip oracle
	feeCap := feeCapFor(baseFee, tip)
	fmt.Println("max priority fee", formatGwei(tip)+", max fee", formatGwei(feeCap))

	fmt.Println(checkPolicy(policy, gasLimit, tip, feeCapFor(gwei(120), tip)))
	fmt.Println(checkPolicy(policy, 200_000, tip, feeCap))
	if err := checkPolicy(policy, gasLimit, tip, feeCap); err != nil {
		panic(err)
	}

	to := common.HexToAddress("0x00000000000000000000000000000000000000aa")
	tx := types.NewTx(&types.DynamicFeeTx{
		ChainID:   big.NewInt(1337),
		Nonce:     0,
		GasTipCap: tip,
		GasFeeCap: feeCap,
		Gas:       gasLimit,
		To:        &to,
		Value:     big.NewInt(10_000_000_000_000_000), // 0.01 ether in wei
	})
	fmt.Println("built unsigned type", tx.Type(), "tx for chain", tx.ChainId())

	for _, b := range []*big.Int{gwei(30), big.NewInt(61_500_000_000), gwei(63)} {
		price, err := effectivePrice(b, tip, feeCap)
		gethTip, gethErr := tx.EffectiveGasTip(b)
		if err != nil {
			fmt.Printf("base %s: not includable (%v)\n", formatGwei(b), gethErr)
			continue
		}
		ourTip := new(big.Int).Sub(price, b)
		fmt.Printf("base %s: pays %s, producer tip %s, geth agrees: %t\n",
			formatGwei(b), formatGwei(price), formatGwei(ourTip), ourTip.Cmp(gethTip) == 0)
	}
	fmt.Println("upfront balance check:", tx.Cost(), "wei")
}

head, err := client.HeaderByNumber(ctx, nil) // latest
if err != nil {
	return err
}
if head.BaseFee == nil {
	return errors.New("no EIP-1559 base fee on this chain; use a legacy fee policy")
}
tip, err := client.SuggestGasTipCap(ctx) // eth_maxPriorityFeePerGas
if err != nil {
	return err
}
hist, err := client.FeeHistory(ctx, 5, nil, []float64{50})
if err != nil {
	return err
}
nextBase := hist.BaseFee[len(hist.BaseFee)-1] // the node's projection for the next block
feeCap := feeCapFor(nextBase, tip)
if err := checkPolicy(policy, gasLimit, tip, feeCap); err != nil {
	return err // alert: the market moved beyond what this service may pay
}

// Native environment only: a real node and a durable store.
if err := store.SaveSigned(ctx, intentID, signed.Nonce(), signed.Hash(), raw); err != nil {
	return err // nothing was sent, so repeating this step is safe
}
sendErr := client.SendTransaction(ctx, signed) // MarshalBinary + eth_sendRawTransaction
receipt, err := client.TransactionReceipt(ctx, signed.Hash())
switch {
case err == nil:
	return store.MarkIncluded(ctx, intentID, receipt.Status, receipt.BlockHash)
case errors.Is(err, ethereum.NotFound):
	// Pending, dropped or never received: resend the same raw bytes later.
	return store.MarkSubmitted(ctx, intentID, sendErr)
default:
	return err // provider trouble: retry the lookup, never the signing
}

package main

import (
	"fmt"
	"math/big"
	"strings"

	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/crypto"
)

const transferABI = `[{"type":"event","name":"Transfer","anonymous":false,"inputs":[
{"name":"from","type":"address","indexed":true},
{"name":"to","type":"address","indexed":true},
{"name":"value","type":"uint256","indexed":false}]}]`

type Transfer struct {
	From  common.Address
	To    common.Address
	Value *big.Int
}

func decodeTransfer(token abi.ABI, want common.Address, lg *types.Log) (Transfer, error) {
	ev := token.Events["Transfer"]
	if lg.Address != want {
		return Transfer{}, fmt.Errorf("emitted by %s, not the token", lg.Address.Hex())
	}
	if len(lg.Topics) != 3 || lg.Topics[0] != ev.ID {
		return Transfer{}, fmt.Errorf("%d topics, not an ERC-20 Transfer", len(lg.Topics))
	}
	var out Transfer
	if err := token.UnpackIntoInterface(&out, "Transfer", lg.Data); err != nil {
		return Transfer{}, err // fills Value from the data section
	}
	var indexed abi.Arguments
	for _, arg := range ev.Inputs {
		if arg.Indexed {
			indexed = append(indexed, arg)
		}
	}
	if err := abi.ParseTopics(&out, indexed, lg.Topics[1:]); err != nil {
		return Transfer{}, err // fills From and To from topics 1 and 2
	}
	return out, nil
}

// deposits credits each delivered log once, keyed by block hash and log index,
// and reverses the credit when the same log comes back with Removed set.
type deposits struct {
	token    abi.ABI
	contract common.Address
	applied  map[string]bool
	balance  map[common.Address]*big.Int
}

func (d *deposits) onLog(lg *types.Log) {
	t, err := decodeTransfer(d.token, d.contract, lg)
	if err != nil {
		fmt.Printf("log %d skipped: %v\n", lg.Index, err)
		return
	}
	key := fmt.Sprintf("%s/%d", lg.BlockHash.Hex(), lg.Index)
	if d.balance[t.To] == nil {
		d.balance[t.To] = new(big.Int)
	}
	switch {
	case lg.Removed && d.applied[key]:
		d.balance[t.To].Sub(d.balance[t.To], t.Value)
		delete(d.applied, key)
		fmt.Printf("log %d removed: reverse %s\n", lg.Index, t.Value)
	case !lg.Removed && !d.applied[key]:
		d.balance[t.To].Add(d.balance[t.To], t.Value)
		d.applied[key] = true
		fmt.Printf("log %d: credit %s from %s\n", lg.Index, t.Value, t.From.Hex())
	}
}

func (d *deposits) onReceipt(r *types.Receipt) {
	fee := new(big.Int).Mul(new(big.Int).SetUint64(r.GasUsed), r.EffectiveGasPrice)
	fmt.Printf("status %d, gas used %d, fee %s wei, %d logs\n", r.Status, r.GasUsed, fee, len(r.Logs))
	if r.Status != types.ReceiptStatusSuccessful {
		return // reverted: the fee was paid, but no token moved
	}
	for _, lg := range r.Logs {
		d.onLog(lg)
	}
}

func main() {
	token, err := abi.JSON(strings.NewReader(transferABI))
	if err != nil {
		panic(err)
	}
	ev := token.Events["Transfer"]
	fmt.Println("topic0", ev.ID.Hex())
	fmt.Println("equals keccak256 of the signature:", ev.ID == crypto.Keccak256Hash([]byte(ev.Sig)))

	contract := common.HexToAddress("0x00000000000000000000000000000000000000c0")
	impostor := common.HexToAddress("0x00000000000000000000000000000000000000ee")
	from := common.HexToAddress("0x1a642f0E3c3aF545E7AcBD38b07251B3990914F1")
	to := common.HexToAddress("0x00000000000000000000000000000000000000bb")
	data, err := ev.Inputs.NonIndexed().Pack(big.NewInt(2_500_000))
	if err != nil {
		panic(err)
	}
	fromTopic, toTopic := common.BytesToHash(from.Bytes()), common.BytesToHash(to.Bytes())
	blockA := common.HexToHash("0xa1")
	ok := &types.Receipt{
		Status: types.ReceiptStatusSuccessful, GasUsed: 51_000,
		EffectiveGasPrice: big.NewInt(32_000_000_000), BlockHash: blockA,
		Logs: []*types.Log{
			{Address: contract, Topics: []common.Hash{ev.ID, fromTopic, toTopic}, Data: data, BlockHash: blockA, Index: 4},
			{Address: impostor, Topics: []common.Hash{ev.ID, fromTopic, toTopic}, Data: data, BlockHash: blockA, Index: 5},
			{Address: contract, Topics: []common.Hash{ev.ID, fromTopic, toTopic, common.BigToHash(big.NewInt(9))}, BlockHash: blockA, Index: 6},
		},
	}
	reverted := &types.Receipt{Status: types.ReceiptStatusFailed, GasUsed: 29_000, EffectiveGasPrice: big.NewInt(32_000_000_000)}

	d := &deposits{token: token, contract: contract, applied: map[string]bool{}, balance: map[common.Address]*big.Int{}}
	d.onReceipt(ok)
	d.onLog(ok.Logs[0]) // a duplicate delivery changes nothing
	d.onReceipt(reverted)
	fmt.Printf("credited to %s: %s\n", to.Hex(), d.balance[to])

	// Reorg: block A leaves the canonical chain, the log is re-sent with Removed
	// set, and the transaction is included again in block B at another index.
	gone := *ok.Logs[0]
	gone.Removed = true
	d.onLog(&gone)
	again := *ok.Logs[0]
	again.BlockHash, again.Index = common.HexToHash("0xb1"), 0
	d.onLog(&again)
	fmt.Printf("credited after reorg: %s\n", d.balance[to])
}

transferID := token.Events["Transfer"].ID
watched := common.BytesToHash(depositAddress.Bytes())
q := ethereum.FilterQuery{
	FromBlock: new(big.Int).SetUint64(from),
	ToBlock:   new(big.Int).SetUint64(to), // bounded range, never open-ended
	Addresses: []common.Address{tokenAddress},
	Topics:    [][]common.Hash{{transferID}, nil, {watched}},
}
logs, err := client.FilterLogs(ctx, q)
if err != nil {
	return err
}
for i := range logs {
	d.onLog(&logs[i]) // the same checks as the offline example
}

package main

import (
	"bytes"
	"errors"
	"fmt"
	"math/big"
	"strings"
	"sync"
	"time"

	"github.com/ethereum/go-ethereum/accounts"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/crypto"
)

const header = " wants you to sign in with your Ethereum account:"

var fields = map[string]bool{"URI": true, "Version": true, "Chain ID": true,
	"Nonce": true, "Issued At": true, "Expiration Time": true}

// recoverPersonal returns the address that produced an EIP-191 personal_sign signature.
func recoverPersonal(message string, sig []byte) (common.Address, error) {
	if len(sig) != crypto.SignatureLength {
		return common.Address{}, errors.New("signature must be 65 bytes")
	}
	s := bytes.Clone(sig) // never mutate the caller's slice
	if s[64] == 27 || s[64] == 28 {
		s[64] -= 27 // wallets send 27/28; go-ethereum expects 0/1
	}
	r, sv := new(big.Int).SetBytes(s[:32]), new(big.Int).SetBytes(s[32:64])
	if !crypto.ValidateSignatureValues(s[64], r, sv, true) {
		return common.Address{}, errors.New("invalid or high-s signature")
	}
	pub, err := crypto.SigToPub(accounts.TextHash([]byte(message)), s)
	if err != nil {
		return common.Address{}, err
	}
	return crypto.PubkeyToAddress(*pub), nil
}

// parse reads the EIP-4361 fields this server checks. A production parser
// should implement the full ABNF, including field order and Resources.
func parse(msg string) (map[string]string, error) {
	lines := strings.Split(msg, "\n")
	if len(lines) < 8 || !strings.HasSuffix(lines[0], header) {
		return nil, errors.New("not a sign-in message")
	}
	f := map[string]string{"Domain": strings.TrimSuffix(lines[0], header), "Address": lines[1]}
	for _, line := range lines[2:] {
		k, v, ok := strings.Cut(line, ": ")
		if !ok || !fields[k] {
			continue // blank lines and the free-text statement
		}
		if _, dup := f[k]; dup {
			return nil, fmt.Errorf("duplicate field %q", k)
		}
		f[k] = v
	}
	return f, nil
}

type Server struct {
	Domain, ChainID string
	mu              sync.Mutex
	nonces          map[string]bool // issued and not yet used
}

func (s *Server) Verify(msg string, sig []byte, now time.Time) (common.Address, error) {
	f, err := parse(msg)
	if err != nil {
		return common.Address{}, err
	}
	if f["Domain"] != s.Domain {
		return common.Address{}, fmt.Errorf("domain %q is not %q", f["Domain"], s.Domain)
	}
	if f["URI"] != "https://"+s.Domain+"/login" || f["Version"] != "1" || f["Chain ID"] != s.ChainID {
		return common.Address{}, errors.New("wrong URI, version or chain")
	}
	exp, err := time.Parse(time.RFC3339, f["Expiration Time"])
	if err != nil || !now.Before(exp) {
		return common.Address{}, errors.New("missing or past expiration time")
	}
	claimed := f["Address"]
	if !common.IsHexAddress(claimed) || common.HexToAddress(claimed).Hex() != claimed {
		return common.Address{}, errors.New("address is not EIP-55 checksummed")
	}
	signer, err := recoverPersonal(msg, sig)
	if err != nil {
		return common.Address{}, err
	}
	if signer != common.HexToAddress(claimed) {
		return common.Address{}, fmt.Errorf("signature recovers %s", signer.Hex())
	}
	s.mu.Lock() // consuming the nonce is the commit point
	defer s.mu.Unlock()
	if !s.nonces[f["Nonce"]] {
		return common.Address{}, errors.New("nonce unknown or already used")
	}
	delete(s.nonces, f["Nonce"])
	return signer, nil
}

func message(domain string, addr common.Address, nonce string, issued time.Time) string {
	return domain + header + "\n" + addr.Hex() + "\n\n" +
		"Sign in to the dashboard.\n\n" +
		"URI: https://" + domain + "/login\nVersion: 1\nChain ID: 1337\n" +
		"Nonce: " + nonce + "\n" +
		"Issued At: " + issued.Format(time.RFC3339) + "\n" +
		"Expiration Time: " + issued.Add(5*time.Minute).Format(time.RFC3339)
}

// walletSign mimics personal_sign: EIP-191 hash, then V shifted to 27/28.
func walletSign(msg string, key []byte) []byte {
	prv, err := crypto.ToECDSA(key)
	if err != nil {
		panic(err)
	}
	sig, err := crypto.Sign(accounts.TextHash([]byte(msg)), prv)
	if err != nil {
		panic(err)
	}
	sig[64] += 27
	return sig
}

func main() {
	testKey := bytes.Repeat([]byte{1}, 32) // TEST KEY ONLY, never funded
	prv, _ := crypto.ToECDSA(testKey)
	user := crypto.PubkeyToAddress(prv.PublicKey)
	now := time.Date(2026, 11, 18, 12, 0, 0, 0, time.UTC) // fixed clock for the example
	srv := &Server{Domain: "app.example.com", ChainID: "1337", nonces: map[string]bool{}}

	// In production each nonce comes from crypto/rand.Text and is stored with a TTL.
	srv.nonces["K7Q2M9XW4PZ3"], srv.nonces["H5R8T2LN6QVA"] = true, true
	msg := message("app.example.com", user, "K7Q2M9XW4PZ3", now)
	sig := walletSign(msg, testKey)
	fmt.Println(strings.Split(msg, "\n")[0])
	fmt.Println("wallet V byte:", sig[64])

	flipped := bytes.Clone(sig)
	flipped[64] = 27 + 28 - flipped[64] // 27 <-> 28: valid, but for another key
	try := func(label, m string, s []byte, at time.Time) {
		addr, err := srv.Verify(m, s, at)
		if err != nil {
			fmt.Printf("%-9s rejected: %v\n", label, err)
			return
		}
		fmt.Printf("%-9s signed in as %s\n", label, addr.Hex())
	}
	try("flipped V", msg, flipped, now)
	try("login", msg, sig, now.Add(30*time.Second))
	try("replay", msg, sig, now.Add(40*time.Second))

	phish := message("evil.example", user, "H5R8T2LN6QVA", now)
	try("phishing", phish, walletSign(phish, testKey), now)
	late := message("app.example.com", user, "H5R8T2LN6QVA", now)
	try("late", late, walletSign(late, testKey), now.Add(6*time.Minute))
}

// Issue: bind each nonce to the pre-login browser session that asked for it.
nonce := rand.Text() // crypto/rand: 26 base32 characters
if _, err := db.ExecContext(ctx,
	`INSERT INTO siwe_nonces (nonce, session_id, expires_at)
	 VALUES ($1, $2, now() + interval '5 minutes')`, nonce, sessionID); err != nil {
	return err
}

// Verify: only after domain, URI, chain, expiry and signature checks pass.
res, err := db.ExecContext(ctx,
	`DELETE FROM siwe_nonces WHERE nonce = $1 AND session_id = $2 AND expires_at > now()`,
	fields["Nonce"], sessionID)
if err != nil {
	return err
}
if n, err := res.RowsAffected(); err != nil || n != 1 {
	return errors.New("nonce unknown, expired or already used")
}

package main

import (
	"context"
	"errors"
	"fmt"
	"math/big"
	"net/http"
	"time"

	"github.com/ethereum/go-ethereum"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/ethclient"
	"github.com/ethereum/go-ethereum/rpc"
)

// Reader is the slice of *ethclient.Client this service depends on.
type Reader interface {
	HeaderByNumber(ctx context.Context, number *big.Int) (*types.Header, error)
	BalanceAtHash(ctx context.Context, account common.Address, block common.Hash) (*big.Int, error)
}

var _ Reader = (*ethclient.Client)(nil) // the real client fits the same interface

type Provider struct {
	Name string
	Reader
}

// fake is an in-memory node: a header per height, a balance per block hash and a
// script of failures returned before any balance read succeeds.
type fake struct {
	headers  map[uint64]*types.Header
	balances map[common.Hash]*big.Int
	failures []error
}

func (f *fake) HeaderByNumber(ctx context.Context, n *big.Int) (*types.Header, error) {
	if h, ok := f.headers[n.Uint64()]; ok {
		return h, nil
	}
	return nil, ethereum.NotFound // what ethclient returns for a null block
}

func (f *fake) BalanceAtHash(ctx context.Context, _ common.Address, block common.Hash) (*big.Int, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if len(f.failures) > 0 {
		err := f.failures[0]
		f.failures = f.failures[1:]
		return nil, err
	}
	if b, ok := f.balances[block]; ok {
		return new(big.Int).Set(b), nil
	}
	return nil, errors.New("header for hash not found")
}

// pin asks every provider for the header at n and accepts a hash only if a strict
// majority of all configured providers return it.
func pin(ctx context.Context, ps []Provider, n uint64) (common.Hash, []Provider, error) {
	answers := make([]common.Hash, len(ps))
	votes := map[common.Hash]int{}
	var best common.Hash
	for i, p := range ps {
		h, err := p.HeaderByNumber(ctx, new(big.Int).SetUint64(n))
		if err != nil {
			fmt.Printf("%s: no header %d (%v), excluded\n", p.Name, n, err)
			continue
		}
		answers[i] = h.Hash() // computed locally from the returned header fields
		votes[answers[i]]++
		if votes[answers[i]] > votes[best] {
			best = answers[i]
		}
	}
	if 2*votes[best] <= len(ps) {
		return common.Hash{}, nil, fmt.Errorf("no majority for block %d", n)
	}
	var agreeing []Provider
	for i, p := range ps {
		switch answers[i] {
		case best:
			agreeing = append(agreeing, p)
		case common.Hash{}:
		default:
			fmt.Printf("%s: reports %s at %d, quarantined\n", p.Name, answers[i].TerminalString(), n)
		}
	}
	return best, agreeing, nil
}

func retryable(err error) bool {
	var httpErr rpc.HTTPError
	if errors.As(err, &httpErr) {
		return httpErr.StatusCode == http.StatusTooManyRequests || httpErr.StatusCode >= 500
	}
	return errors.Is(err, context.DeadlineExceeded)
}

type Backoff struct {
	Attempts   int
	Base, Max  time.Duration
	Sleep      func(context.Context, time.Duration) error
	PerAttempt time.Duration
}

// balance tries each agreeing provider in order with bounded, growing waits.
func balance(ctx context.Context, ps []Provider, b Backoff, a common.Address, block common.Hash) (*big.Int, error) {
	for _, p := range ps {
		wait := b.Base
		for attempt := 1; attempt <= b.Attempts; attempt++ {
			callCtx, cancel := context.WithTimeout(ctx, b.PerAttempt)
			v, err := p.BalanceAtHash(callCtx, a, block)
			cancel()
			if err == nil {
				fmt.Printf("%s: balance at %s = %s wei\n", p.Name, block.TerminalString(), v)
				return v, nil
			}
			if !retryable(err) || attempt == b.Attempts {
				fmt.Printf("%s: attempt %d: %v, next provider\n", p.Name, attempt, err)
				break
			}
			fmt.Printf("%s: attempt %d: %v, retry in %v\n", p.Name, attempt, err, wait)
			if err := b.Sleep(ctx, wait); err != nil {
				return nil, err
			}
			wait = min(2*wait, b.Max)
		}
	}
	return nil, errors.New("all providers failed")
}

func main() {
	header := func(n uint64, root byte) *types.Header {
		return &types.Header{Number: new(big.Int).SetUint64(n), Difficulty: new(big.Int), Root: common.Hash{root}}
	}
	canonical, fork := header(100, 0xaa), header(100, 0xbb)
	limited := rpc.HTTPError{StatusCode: 429, Status: "429 Too Many Requests"}
	funds := map[common.Hash]*big.Int{canonical.Hash(): big.NewInt(5_000_000_000_000_000_000)}

	providers := []Provider{
		{"alpha", &fake{headers: map[uint64]*types.Header{100: canonical}, balances: funds,
			failures: []error{limited, limited, limited}}},
		{"beta", &fake{headers: map[uint64]*types.Header{100: canonical}, balances: funds}},
		{"gamma", &fake{headers: map[uint64]*types.Header{100: canonical}, balances: funds}},
		{"delta", &fake{headers: map[uint64]*types.Header{100: fork}}},
		{"epsilon", &fake{headers: map[uint64]*types.Header{99: header(99, 0xaa)}}},
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	hash, agreeing, err := pin(ctx, providers, 100)
	if err != nil {
		panic(err)
	}
	fmt.Printf("pinned block 100 = %s, agreed by %d of %d\n", hash.TerminalString(), len(agreeing), len(providers))

	var slept time.Duration
	policy := Backoff{Attempts: 3, Base: 100 * time.Millisecond, Max: time.Second, PerAttempt: 500 * time.Millisecond,
		Sleep: func(_ context.Context, d time.Duration) error { slept += d; return nil }}
	if _, err := balance(ctx, agreeing, policy, common.HexToAddress("0xbb"), hash); err != nil {
		panic(err)
	}
	fmt.Println("total backoff:", slept)
}

type limited struct {
	Reader
	lim *rate.Limiter
}

func (l limited) BalanceAtHash(ctx context.Context, a common.Address, h common.Hash) (*big.Int, error) {
	if err := l.lim.Wait(ctx); err != nil { // errors out if the wait would pass the deadline
		return nil, err
	}
	return l.Reader.BalanceAtHash(ctx, a, h)
}

func dial(ctx context.Context, name, url string, want *big.Int) (Provider, error) {
	rc, err := rpc.DialOptions(ctx, url, rpc.WithHTTPClient(&http.Client{Timeout: 10 * time.Second}))
	if err != nil {
		return Provider{}, err
	}
	client := ethclient.NewClient(rc)
	id, err := client.ChainID(ctx)
	if err != nil || id.Cmp(want) != 0 {
		client.Close()
		return Provider{}, fmt.Errorf("%s: chain %v, want %v (err %v)", name, id, want, err)
	}
	return Provider{Name: name, Reader: limited{client, rate.NewLimiter(20, 5)}}, nil
}

// After dialing: choose the coordinate once, then confirm it across providers.
fin, err := providers[0].HeaderByNumber(ctx, big.NewInt(int64(rpc.FinalizedBlockNumber)))
if err != nil {
	return err
}
hash, agreeing, err := pin(ctx, providers, fin.Number.Uint64())

package main

import "fmt"

type Principal struct{ Subject, Tenant, Role string }
type Document struct{ Tenant, Owner string }

func canRead(p Principal, d Document) bool {
	return p.Subject != "" && p.Tenant == d.Tenant && (p.Subject == d.Owner || p.Role == "auditor")
}
func main() {
