	dsn, err := url.Parse("postgres://orders:" + canary + "@db.internal.example:5432/orders")
	if err != nil {
		panic(err)
	}
	fmt.Println("url String leaks:", strings.Contains(dsn.String(), canary))
	fmt.Println(fmt.Errorf("connect %s: %w", dsn.Redacted(), errors.New("connection refused")))
	fmt.Println("leak found in any output:", strings.Contains(buf.String(), canary))
}

